def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bags = image_patch.find("bag")
    bottles = image_patch.find("bottle")
    beds = image_patch.find("bed")

    if not bags or not bottles or not beds:
        return image_patch

    bottle_bed_distance = min(distance(bottle, bed) for bottle in bottles for bed in beds)

    near_bag = None
    for bag in bags:
        for bottle in bottles:
            for bed in beds:
                if abs(distance(bag, bottle) + distance(bag, bed) - bottle_bed_distance) < 0.1:
                    near_bag = bag
                    break
            if near_bag:
                break
        if near_bag:
            break

    return near_bag if near_bag else bags[0]

